def evolved_p92(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # Formula: x[i] = (i - N//2)**2, squared distance to center index.
    # Position-based, compute locally, no collective needed.
    idx = torch.arange(N, device=x.device)
    return ((idx - N // 2) ** 2).contiguous().to(x.dtype)

